# Which service answers which /api path. Shared by the dev (nginx.conf) and production (prod/nginx.conf) gateways.
map $uri $service {
    default "";

    ~^/api/(auth|me|areas|cities)/                                 auth;
    ~^/api/admin/(areas|users)/                                    auth;

    ~^/api/(catalog|categories|products|services)/                 catalog;

    ~^/api/(order|cart|orders|bookings)/                           order;
    ~^/api/admin/(orders|bookings|warranty-claims|order-stats)/    order;

    ~^/api/(provider|providers)/                                   provider;
    ~^/api/admin/(providers|jobs|payouts|provider-stats|safety|review-disputes|insurance-plans|insurance-claims|training-modules)/  provider;

    ~^/api/(custom_request|custom-requests)/                       custom-request;
    ~^/api/admin/custom-requests/                                  custom-request;

    ~^/api/media/                                                  media;
    ~^/api/admin/media/                                            media;

    ~^/api/(subscription|subscriptions|subscription-plans|subscription-addons|meal-menu)/   subscription;
    ~^/api/admin/(subscriptions|plan-prices|student-verifications|subscription-stats)/      subscription;

    ~^/api/(payment|payments)/                                     payment;
    ~^/api/admin/(payments|refunds)/                               payment;

    ~^/api/chat/                                                   chat;
    ~^/api/admin/chat/                                             chat;

    ~^/api/(notification|notifications)/                           notification;
    ~^/api/admin/notifications/                                    notification;

    ~^/api/(city|issues|community)/                                city;
    ~^/api/admin/(issues|authorities|community)/                   city;

    ~^/api/loyalty/                                                loyalty;
    ~^/api/admin/loyalty/                                          loyalty;

    ~^/api/(b2b)/                                                  b2b;
    ~^/api/admin/b2b/                                              b2b;

    ~^/api/(analytics)/                                            analytics;
    ~^/api/admin/analytics/                                        analytics;
}
